/** Package name of the addon that exposes the MCP (Model Context Protocol) server. */
const MCP_ADDON_NAME = '@storybook/addon-mcp';

/** Default MCP endpoint used when the addon does not specify a custom one. */
const DEFAULT_MCP_ENDPOINT = '/mcp';

/** Current schema version of the runtime instance record file format. */
export const RUNTIME_INSTANCE_SCHEMA_VERSION = 1 as const;

/**
 * Describes whether the AI integration (MCP) addon is available for a running Storybook instance,
 * and how to reach it when it is.
 */
export type McpMetadata =
  | { status: 'not-installed' }
  | { status: 'ready'; endpoint: string };

/**
 * A record describing a single running Storybook instance. These are written to disk so that
 * external tools can discover running instances and their capabilities.
 */
export interface RuntimeInstanceRecord {
  /** Version of this record's schema. */
  schemaVersion: typeof RUNTIME_INSTANCE_SCHEMA_VERSION;
  /** Stable identifier for this instance, also used as the record's file name. */
  instanceId: string;
  /** Origin (protocol + host + port) the instance is served from, without any query parameters. */
  url: string;
  /** Absolute path to the working directory the instance was started from. */
  cwd: string;
  /** ISO 8601 timestamp of when the instance record was first created. */
  startedAt: string;
  /** ISO 8601 timestamp of when the instance record was last updated. */
  updatedAt: string;
  /** Availability of the AI integration (MCP) addon for this instance. */
  mcp: McpMetadata;
}

/** Configuration subset needed to derive MCP metadata from a resolved main config. */
type MainConfigWithAddons = Pick<StorybookConfigRaw, 'addons'> | { addons?: Preset[] };

/**
 * Inspects the resolved main config and reports whether the AI integration (MCP) addon is
 * installed, and if so, which endpoint it is served from.
 *
 * - Returns `{ status: 'not-installed' }` when `@storybook/addon-mcp` is not in the `addons` array.
 * - Returns `{ status: 'ready', endpoint: '/mcp' }` when it is present as a plain string.
 * - Returns `{ status: 'ready', endpoint }` when it is present as an object, using
 *   `options.endpoint` when provided (falling back to the default endpoint otherwise).
 */
export function getMcpMetadataFromMainConfig(mainConfig?: MainConfigWithAddons): McpMetadata {
  const addons = mainConfig?.addons ?? [];

  const mcpAddon = addons.find((addon) => {
    if (typeof addon === 'string') {
      return addon === MCP_ADDON_NAME;
    }
    return addon?.name === MCP_ADDON_NAME;
  });

  if (!mcpAddon) {
    return { status: 'not-installed' };
  }

  if (typeof mcpAddon === 'string') {
    return { status: 'ready', endpoint: DEFAULT_MCP_ENDPOINT };
  }

  const endpoint = mcpAddon.options?.endpoint ?? DEFAULT_MCP_ENDPOINT;
  return { status: 'ready', endpoint };
}

/** Options for {@link createRuntimeInstanceRecord}. */
export interface CreateRuntimeInstanceRecordOptions {
  /** Stable identifier for this instance, also used as the record's file name. */
  instanceId: string;
  /** URL the instance is served from. Only the origin is stored; query parameters are dropped. */
  address: string;
  /** Working directory the instance was started from. Resolved to an absolute path. */
  cwd: string;
  /** Timestamp used for both `startedAt` and `updatedAt`. */
  now: Date | number;
  /** MCP metadata for this instance. Defaults to `{ status: 'not-installed' }`. */
  mcp?: McpMetadata;
}

/**
 * Builds a {@link RuntimeInstanceRecord} from the given options, normalizing the address to its
 * origin, resolving the working directory to an absolute path, and stamping the timestamps.
 */
export function createRuntimeInstanceRecord({
  instanceId,
  address,
  cwd,
  now,
  mcp,
}: CreateRuntimeInstanceRecordOptions): RuntimeInstanceRecord {
  const timestamp = new Date(now).toISOString();

  return {
    schemaVersion: RUNTIME_INSTANCE_SCHEMA_VERSION,
    instanceId,
    url: new URL(address).origin,
    cwd: isAbsolute(cwd) ? cwd : resolve(cwd),
    startedAt: timestamp,
    updatedAt: timestamp,
    mcp: mcp ?? { status: 'not-installed' },
  };
}

/** Options for {@link writeRuntimeInstanceRecord}. */
export interface WriteRuntimeInstanceRecordOptions {
  /** Directory in which the record file should be written. */
  registryDir: string;
  /** The record to persist. */
  record: RuntimeInstanceRecord;
}

/**
 * Persists a runtime instance record to `<registryDir>/<instanceId>.json`.
 *
 * The write is atomic: the JSON is first written to a uniquely-named temporary file in the same
 * directory and then renamed into place, so that external readers never observe a partially
 * written file and only the final `.json` file is left behind.
 *
 * Resolves to the absolute path of the written record file.
 */
export async function writeRuntimeInstanceRecord({
  registryDir,
  record,
}: WriteRuntimeInstanceRecordOptions): Promise<string> {
  await mkdir(registryDir, { recursive: true });

  const recordPath = join(registryDir, `${record.instanceId}.json`);
  const tempPath = join(registryDir, `.${record.instanceId}.${randomUUID()}.tmp`);

  const contents = JSON.stringify(record, null, 2);

  try {
    await writeFile(tempPath, contents, 'utf8');
    await rename(tempPath, recordPath);
  } catch (error) {
    // Make sure a failed write never leaves a stray temporary file behind.
    await rm(tempPath, { force: true });
    throw error;
  }

  return recordPath;
}

/** Result of {@link writeStorybookRuntimeInstanceRecord}. */
export interface StorybookRuntimeInstanceRecordHandle {
  /** Absolute path to the written record file. */
  recordPath: string;
  /** The record that was written. */
  record: RuntimeInstanceRecord;
  /** Removes the record file from disk. Safe to call multiple times. */
  cleanup: () => Promise<void>;
}

